/// GPU adapter information for hardware acceleration
class GpuInfo {
  final bool available;
  final String adapterName;
  final String backend;
  final int vramBytes;
  final List<String> supportedEffects;
  final bool isHardwareEncoderAvailable;

  const GpuInfo({
    this.available = false,
    this.adapterName = '',
    this.backend = '',
    this.vramBytes = 0,
    this.supportedEffects = const [],
    this.isHardwareEncoderAvailable = false,
  });

  factory GpuInfo.fromJson(Map<String, dynamic> json) => GpuInfo(
        available: json['available'] as bool? ?? false,
        adapterName: json['adapter_name'] as String? ?? '',
        backend: json['backend'] as String? ?? '',
        vramBytes: json['vram_bytes'] as int? ?? 0,
        supportedEffects: (json['supported_effects'] as List?)
                ?.map((e) => e as String)
                .toList() ??
            [],
        isHardwareEncoderAvailable:
            json['is_hardware_encoder_available'] as bool? ?? false,
      );

  /// Human-readable VRAM size
  String get vramFormatted {
    if (vramBytes >= 1073741824) {
      return '${(vramBytes / 1073741824).toStringAsFixed(1)} GB';
    } else if (vramBytes >= 1048576) {
      return '${(vramBytes / 1048576).toStringAsFixed(1)} MB';
    } else if (vramBytes > 0) {
      return '${(vramBytes / 1024).toStringAsFixed(1)} KB';
    }
    return 'Unknown';
  }
}

// ═══════════════════════════════════════════════════════════════════════
// System Monitoring DTOs
// ═══════════════════════════════════════════════════════════════════════

/// Memory pressure level
enum MemoryPressureLevel {
  normal,
  warning,
  critical;

  static MemoryPressureLevel fromString(String name) {
    switch (name) {
      case 'warning':
        return MemoryPressureLevel.warning;
      case 'critical':
        return MemoryPressureLevel.critical;
      default:
        return MemoryPressureLevel.normal;
    }
  }
}

/// System resource usage snapshot
class SystemMetrics {
  final int memoryRssBytes;
  final int memoryPeakBytes;
  final int systemAvailableBytes;
  final int systemTotalBytes;
  final MemoryPressureLevel pressureLevel;
  final int cachedFrames;
  final int cachedAudioBuffers;

  const SystemMetrics({
    required this.memoryRssBytes,
    required this.memoryPeakBytes,
    required this.systemAvailableBytes,
    required this.systemTotalBytes,
    required this.pressureLevel,
    required this.cachedFrames,
    required this.cachedAudioBuffers,
  });

  factory SystemMetrics.fromJson(Map<String, dynamic> json) => SystemMetrics(
        memoryRssBytes: json['memory_rss_bytes'] as int,
        memoryPeakBytes: json['memory_peak_bytes'] as int,
        systemAvailableBytes: json['system_available_bytes'] as int,
        systemTotalBytes: json['system_total_bytes'] as int,
        pressureLevel: MemoryPressureLevel.fromString(
            json['pressure_level'] as String? ?? 'normal'),
        cachedFrames: json['cached_frames'] as int,
        cachedAudioBuffers: json['cached_audio_buffers'] as int,
      );

  /// Human-readable RSS
  String get rssFormatted => _formatBytes(memoryRssBytes);

  /// Human-readable peak
  String get peakFormatted => _formatBytes(memoryPeakBytes);

  /// Human-readable available
  String get availableFormatted => _formatBytes(systemAvailableBytes);

  static String _formatBytes(int bytes) {
    if (bytes >= 1073741824) {
      return '${(bytes / 1073741824).toStringAsFixed(1)} GB';
    } else if (bytes >= 1048576) {
      return '${(bytes / 1048576).toStringAsFixed(1)} MB';
    } else if (bytes >= 1024) {
      return '${(bytes / 1024).toStringAsFixed(1)} KB';
    }
    return '$bytes B';
  }
}

// ═══════════════════════════════════════════════════════════════════════
// Engine API
// ═══════════════════════════════════════════════════════════════════════

/// The main API class exposed to Flutter via flutter_rust_bridge v2.
///
/// When the native engine library is unavailable, the noOp constructor
/// creates an instance that throws [UnimplementedError] on every method
/// call, allowing the app to degrade gracefully.
class EditorsProEngineApi {
  /// Whether this API instance is in noOp (degraded) mode.
  final bool _isNoOp;

  /// The owning [RustLib] runtime, used to invoke the native dispatch
  /// function. Null when in noOp mode.
  final RustLib? _runtime;

  /// Create a real engine API instance backed by the FFI runtime.
  EditorsProEngineApi({required RustLib runtime})
      : _isNoOp = false,
        _runtime = runtime;

  /// Create a no-op API instance for graceful degradation when
  /// the native engine library is unavailable.
  EditorsProEngineApi.noOp()
      : _isNoOp = true,
        _runtime = null;

  /// Check whether this API instance has a working FFI connection.
  bool get isEngineAvailable => !_isNoOp;

  /// Execute a Rust method via the FFI dispatcher.
  ///
  /// Phase A.1: this now actually calls into the native
  /// `editors_pro_dispatch` function exposed by
  /// `engine/src/api/ffi_dispatch.rs`, replacing the previous stub
  /// that threw `UnimplementedError` on every call.
  ///
  /// The dispatcher returns a JSON string of the form
  /// `{"ok": true, "data": ...}` or `{"ok": false, "error": "..."}`.
  /// This method decodes that envelope and either returns the `data`
  /// field cast to `T`, or throws the error message.
  ///
  /// If the engine is not available, throws [UnimplementedError].
  Future<T> _call<T>(String method, Map<String, dynamic> args) async {
    final runtime = _runtime;
    if (_isNoOp || runtime == null) {
      throw UnimplementedError(
        'Bridge method "$method" cannot run: engine is in noOp mode. '
        'Ensure libeditors_pro_engine.so is bundled and RustLib.init() '
        'successfully loaded the native library.',
      );
    }

    final argsJson = args.isEmpty ? '{}' : _encodeArgs(args);
    final responseJson = await runtime.dispatchAsync(method, argsJson);
    final envelope = _decodeEnvelope(responseJson);

    if (envelope['ok'] != true) {
      final err = envelope['error'] ?? 'unknown error';
      throw Exception('Engine $method failed: $err');
    }
    final data = envelope['data'];
    return data as T;
  }

  /// Encode Dart args to a JSON string. Uses [jsonEncode] which handles
  /// nested maps and lists but not BigInt — callers must convert BigInt
  /// values to strings before passing them in (which they already do).
  static String _encodeArgs(Map<String, dynamic> args) {
    return args.isEmpty
        ? '{}'
        : jsonEncode(args, toEncodable: (obj) {
            if (obj is BigInt) return obj.toString();
            // Try to call toJson() on the object if it has one.
            // This handles DTOs like BridgeProjectSettings, BridgeExportSettings, etc.
            // that were passed as objects rather than pre-converted Maps.
            // Using a dynamic dispatch with try/catch because `obj?.toJson`
            // would try to access `toJson` as a getter (tear-off) rather
            // than checking if it's a method.
            try {
              final json = (obj as dynamic).toJson();
              if (json is Map) return json;
            } catch (_) {
              // No toJson method — fall through to toString()
            }
            return obj.toString();
          });
  }

  /// Decode a JSON envelope returned by the dispatcher.
  static Map<String, dynamic> _decodeEnvelope(String json) {
    final decoded = jsonDecode(json);
    if (decoded is! Map) {
      throw FormatException(
        'Expected JSON object from dispatcher, got: ${decoded.runtimeType}',
      );
    }
    return decoded.cast<String, dynamic>();
  }

  // ─── Lifecycle ────────────────────────────────────────────────────

  /// Initialize the engine.
  Future<void> initialize() async {
    return await _call<void>('initialize', {});
  }

  // ─── Project Operations ───────────────────────────────────────────

  /// Create a new project with the given name and optional settings.
  Future<ProjectInfo> createProject({
    required String name,
    BridgeProjectSettings? settings,
  }) async {
    final result = await _call<dynamic>('create_project', {
      'name': name,
      'settings': settings?.toJson(),
    });
    return ProjectInfo.fromJson(result as Map<String, dynamic>);
  }

  /// Import a media file into the current project.
  Future<MediaAssetInfo> importMedia({required String filePath}) async {
    final result =
        await _call<dynamic>('import_media', {'file_path': filePath});
    return MediaAssetInfo.fromJson(result as Map<String, dynamic>);
  }

  /// Restore persisted asset metadata while preserving its stable ID.
  Future<void> restoreMediaAsset({required MediaAssetInfo asset}) async {
    return await _call<void>('restore_media_asset', {'asset': asset.toJson()});
  }

  /// Save the current project to an .epp file.
  Future<void> saveProject({required String filePath}) async {
    return await _call<void>('save_project', {'path': filePath});
  }

  /// Load a project from an .epp file.
  Future<ProjectInfo> loadProject({required String filePath}) async {
    final result = await _call<dynamic>('load_project', {'path': filePath});
    return ProjectInfo.fromJson(result as Map<String, dynamic>);
  }

  /// Get information about the current project.
  Future<ProjectInfo?> getProjectInfo() async {
