  /// Remove a clip from the timeline.
  Future<void> removeClip({required String clipId}) async {
    return await _call<void>('remove_clip', {'clip_id': clipId});
  }

  /// Get the timeline duration in milliseconds.
  Future<BigInt> getTimelineDuration() async {
    final result = await _call<dynamic>('get_timeline_duration', {});
    return BigInt.parse(result.toString());
  }

  /// Get the full timeline state from the engine.
  Future<TimelineState?> getTimelineState() async {
    final result = await _call<dynamic>('get_timeline_state', {});
    if (result == null) return null;
    return TimelineState.fromJson(result as Map<String, dynamic>);
  }

  // ─── Preview ─────────────────────────────────────────────────────

  /// Render a single preview frame at the given timestamp.
  Future<typed_data.Uint8List> getFrame({required BigInt timeMs}) async {
    final result = await _call<dynamic>('get_frame', {
      'time_ms': timeMs.toString(),
    });
    // The dispatcher returns a JSON array of ints (from Rust Vec<u8>).
    // jsonDecode produces a List<dynamic>, which we convert to Uint8List.
    if (result is typed_data.Uint8List) return result;
    if (result is List) {
      return typed_data.Uint8List.fromList(result.cast<int>());
    }
    throw FormatException(
      'Expected Uint8List or List from get_frame, got ${result.runtimeType}',
    );
  }

  /// Phase C.14: stream frames from `startMs` to `endMs` at the given `fps`.
  ///
  /// Returns a `Stream<BridgeFrame>` that the caller can listen on.
  /// Each frame is pushed by the Rust side as soon as it's decoded,
  /// eliminating FFI round-trip latency for preview playback.
  ///
  /// **Note**: this method requires real flutter_rust_bridge bindings
  /// (i.e., `flutter_rust_bridge_codegen generate` has been run). With
  /// the FFI dispatcher fallback, this method throws `UnimplementedError`
  /// — use `getFrame` polling as a fallback.
  ///
  /// To cancel the stream, cancel the `StreamSubscription` returned by
  /// `listen()`. The Rust side detects the closed sink and exits.
  Stream<BridgeFrame> streamFrames({
    required BigInt startMs,
    required BigInt endMs,
    required double fps,
  }) {
    // The dispatcher can't pass a StreamSink across plain C FFI, so
    // this method only works with real flutter_rust_bridge bindings.
    // When codegen is run, this method will be replaced with a real
    // implementation that creates a StreamSink and passes it to
    // `RustLib.instance.api.stream_frames(start_ms, end_ms, fps, sink)`.
    //
    // For now, throw UnimplementedError so callers know to fall back
    // to `getFrame` polling.
    throw UnimplementedError(
      'streamFrames requires flutter_rust_bridge_codegen to be run. '
      'Until then, use getFrame() polling as a fallback.',
    );
  }

  // ─── Export ──────────────────────────────────────────────────────

  /// Export the project as a video file (synchronous).
  Future<BridgeExportResult> exportVideo({
    required String outputPath,
    required BridgeExportSettings settings,
  }) async {
    final result = await _call<dynamic>('export_video', {
      'output_path': outputPath,
      'settings': settings.toJson(),
    });
    return BridgeExportResult.fromJson(result as Map<String, dynamic>);
  }

  /// Request cancellation of an in-progress export.
  Future<void> cancelExport() async {
    final runtime = _runtime;
    if (_isNoOp || runtime == null) {
      throw UnimplementedError('Native export cancellation is unavailable.');
    }
    if (runtime.hasDirectExportCancellation) {
      runtime.requestExportCancellation();
      return;
    }
    await _call<void>('cancel_export', {});
  }

  /// Clear a previous cancellation before starting a new export.
  void prepareExport() {
    final runtime = _runtime;
    if (_isNoOp || runtime == null) return;
    runtime.prepareExport();
  }

  /// Read the lock-free export snapshot without waiting for the engine queue.
  BridgeExportProgress getExportProgress() {
    final runtime = _runtime;
    if (_isNoOp || runtime == null || !runtime.hasDirectExportProgress) {
      throw UnimplementedError('Native export progress is unavailable.');
    }
    final json = jsonDecode(runtime.readExportStatus());
    if (json is! Map<String, dynamic>) {
      throw const FormatException('Invalid native export progress response.');
    }
    return BridgeExportProgress.fromJson(json);
  }

  /// Export the project with progress reporting via callback.
  Future<BridgeExportResult> exportVideoWithCallback({
    required String outputPath,
    required BridgeExportSettings settings,
  }) async {
    final result = await _call<dynamic>('export_video_with_callback', {
      'output_path': outputPath,
      'settings': settings.toJson(),
    });
    return BridgeExportResult.fromJson(result as Map<String, dynamic>);
  }

  /// Export the project with streaming progress.
  Stream<BridgeExportProgress> exportVideoStreaming({
    required String outputPath,
    required BridgeExportSettings settings,
  }) {
    final controller = StreamController<BridgeExportProgress>();
    _call<BridgeExportResult>('export_video_streaming', {
      'output_path': outputPath,
      'settings': settings.toJson(),
    }).then((result) {
      controller.add(const BridgeExportProgress(
        progress: 1.0,
        currentFrame: 0,
        totalFrames: 0,
        estimatedSecondsRemaining: 0,
        stageName: 'Complete',
      ));
      controller.close();
    }).catchError((error) {
      controller.addError(error as Object);
      controller.close();
    });
    return controller.stream;
  }

